mapper.select:
WITH risk_rows AS ( SELECT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id, ra.risk_grade, ra.shortage_yn, ra.reason_message, ra.updated_at, ROW_NUMBER() OVER ( PARTITION BY ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) ORDER BY ra.updated_at DESC, ra.risk_assessment_id DESC ) AS rn FROM risk_assessment ra INNER JOIN inventory_balance ib ON ib.inventory_balance_id = ra.inventory_balance_id AND ib.is_deleted = 0 WHERE ra.is_deleted = 0 ), risk_latest AS ( SELECT sku_id, sales_point_id, CASE risk_grade WHEN 'GOOD' THEN 'SAFE' WHEN 'WARNING' THEN 'CAUTION' WHEN 'CRITICAL' THEN 'DANGER' ELSE risk_grade END AS risk_grade, CASE WHEN risk_grade IS NULL THEN 'UNASSESSED' ELSE 'ASSESSED' END AS assessment_status, shortage_yn, reason_message AS risk_reason FROM risk_rows WHERE rn = 1 ), valid_scope_keys AS ( SELECT DISTINCT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id FROM inventory_balance ib INNER JOIN sku s ON s.sku_id = ib.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id
), sku_risk_agg AS ( SELECT scope.sku_id, CASE WHEN COUNT(*) <> COUNT(r.risk_grade) THEN NULL WHEN SUM(CASE WHEN r.risk_grade = 'DANGER' THEN 1 ELSE 0 END) > 0 THEN 'DANGER' WHEN SUM(CASE WHEN r.risk_grade = 'CAUTION' THEN 1 ELSE 0 END) > 0 THEN 'CAUTION' WHEN SUM(CASE WHEN r.risk_grade = 'NORMAL' THEN 1 ELSE 0 END) > 0 THEN 'NORMAL' WHEN SUM(CASE WHEN r.risk_grade = 'SAFE' THEN 1 ELSE 0 END) > 0 THEN 'SAFE' ELSE NULL END AS risk_grade, CASE WHEN COUNT(*) = COUNT(r.risk_grade) THEN 'ASSESSED' ELSE 'UNASSESSED' END AS assessment_status, CASE WHEN SUM(CASE WHEN r.shortage_yn = 'Y' THEN 1 ELSE 0 END) > 0 THEN 'Y' ELSE 'N' END AS shortage_yn FROM valid_scope_keys scope LEFT JOIN risk_latest r ON r.sku_id = scope.sku_id AND r.sales_point_id = scope.sales_point_id GROUP BY scope.sku_id ), candidate_keys AS ( SELECT DISTINCT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id FROM inventory_balance ib INNER JOIN sku s ON s.sku_id = ib.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id LEFT JOIN sku_risk_agg sr ON sr.sku_id = ib.sku_id
), candidate_balance_base AS ( SELECT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id, CASE WHEN ib.stock_sales_point_id IS NOT NULL THEN 'OWNED' WHEN ib.allocated_sales_point_id IS NOT NULL THEN 'ALLOCATED_ONLY' ELSE 'CENTER_ONLY' END AS sales_point_state, ib.allocated_sales_point_id, ib.warehouse_id, ib.lot_id, ib.on_hand_qty, ib.reserved_qty, ib.updated_at, l.lot_status, l.expiry_date, l.sale_stop_date FROM inventory_balance ib INNER JOIN candidate_keys ck ON ck.sku_id = ib.sku_id AND ck.sales_point_id = NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) LEFT JOIN warehouse active_w ON active_w.warehouse_id = ib.warehouse_id AND active_w.is_deleted = 0 AND active_w.active_yn = 'Y' LEFT JOIN lot l ON l.lot_id = ib.lot_id AND l.is_deleted = 0 WHERE ib.is_deleted = 0 ), disposal_candidate_skus AS ( SELECT DISTINCT sku_id FROM candidate_balance_base ), ranked_disposal_forecast AS ( SELECT df.forecast_id, df.sku_id, df.sales_point_id, df.predicted_qty_d7, df.predicted_qty_d14, df.predicted_qty_d30, ROW_NUMBER() OVER ( PARTITION BY df.sku_id, df.sales_point_id ORDER BY df.base_date DESC, df.updated_at DESC, df.forecast_id DESC ) AS rn FROM demand_forecast df INNER JOIN ml_model_version mv ON mv.model_version_id = df.model_version_id AND mv.status = 'ACTIVE' AND mv.is_deleted = 0 INNER JOIN disposal_candidate_skus dcs ON dcs.sku_id = df.sku_id WHERE df.is_deleted = 0 AND df.base_date <= TRUNC(CAST(#{asOfDate} AS DATE)) AND df.forecast_source <> 'DUMMY_BASELINE' ), latest_disposal_forecast AS ( SELECT forecast_id, sku_id, sales_point_id, predicted_qty_d7, predicted_qty_d14, predicted_qty_d30 FROM ranked_disposal_forecast WHERE rn = 1 ), disposal_lot_dates AS ( SELECT cbb.sku_id, cbb.allocated_sales_point_id, cbb.on_hand_qty, cbb.lot_status, CASE WHEN cbb.expiry_date IS NOT NULL AND cbb.sale_stop_date IS NOT NULL THEN LEAST(TRUNC(cbb.expiry_date), TRUNC(cbb.sale_stop_date)) WHEN cbb.expiry_date IS NOT NULL THEN TRUNC(cbb.expiry_date) WHEN cbb.sale_stop_date IS NOT NULL THEN TRUNC(cbb.sale_stop_date) END AS sale_end_date FROM candidate_balance_base cbb ), disposal_lots AS ( SELECT sku_id, allocated_sales_point_id, on_hand_qty, sale_end_date FROM disposal_lot_dates WHERE on_hand_qty > 0 AND (lot_status IS NULL OR lot_status NOT IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED')) AND sale_end_date > TRUNC(CAST(#{asOfDate} AS DATE)) AND sale_end_date <= TRUNC(CAST(#{asOfDate} AS DATE)) + 30 ), disposal_scope AS ( SELECT sku_id, allocated_sales_point_id, SUM(CASE WHEN sale_end_date <= TRUNC(CAST(#{asOfDate} AS DATE)) + 7 THEN on_hand_qty ELSE 0 END) AS expiring_qty_d7, SUM(CASE WHEN sale_end_date <= TRUNC(CAST(#{asOfDate} AS DATE)) + 14 THEN on_hand_qty ELSE 0 END) AS expiring_qty_d14, SUM(on_hand_qty) AS expiring_qty_d30 FROM disposal_lots GROUP BY sku_id, allocated_sales_point_id ), disposal_by_sku AS ( SELECT ds.sku_id, SUM(CASE WHEN ds.allocated_sales_point_id IS NULL OR lf.forecast_id IS NULL OR lf.predicted_qty_d7 IS NULL OR lf.predicted_qty_d14 IS NULL OR lf.predicted_qty_d30 IS NULL OR lf.predicted_qty_d7 < 0 OR lf.predicted_qty_d14 < 0 OR lf.predicted_qty_d30 < 0 OR lf.predicted_qty_d7 > lf.predicted_qty_d14 OR lf.predicted_qty_d14 > lf.predicted_qty_d30 THEN ds.expiring_qty_d30 ELSE GREATEST( 0, ds.expiring_qty_d7 - lf.predicted_qty_d7, ds.expiring_qty_d14 - lf.predicted_qty_d14, ds.expiring_qty_d30 - lf.predicted_qty_d30 ) END) AS expected_disposal_qty FROM disposal_scope ds LEFT JOIN latest_disposal_forecast lf ON lf.sku_id = ds.sku_id AND lf.sales_point_id = ds.allocated_sales_point_id GROUP BY ds.sku_id ), candidate_sku_agg AS ( SELECT cbb.sku_id, SUM(cbb.on_hand_qty + cbb.reserved_qty) AS current_qty, SUM(CASE WHEN cbb.lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (cbb.expiry_date IS NOT NULL AND TRUNC(cbb.expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (cbb.sale_stop_date IS NOT NULL AND TRUNC(cbb.sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE cbb.on_hand_qty END) AS available_qty, SUM(CASE WHEN cbb.lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (cbb.expiry_date IS NOT NULL AND TRUNC(cbb.expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (cbb.sale_stop_date IS NOT NULL AND TRUNC(cbb.sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE cbb.reserved_qty END) AS reserved_qty, COUNT(DISTINCT cbb.lot_id) AS lot_count, TRUNC(MIN(CASE WHEN cbb.expiry_date IS NOT NULL THEN TRUNC(cbb.expiry_date) - TRUNC(CAST(#{asOfDate} AS DATE)) END)) AS nearest_expiry_days, MIN(cbb.expiry_date) AS nearest_expiry_date, CASE WHEN SUM(CASE WHEN cbb.lot_status = 'EXPIRED' OR (cbb.expiry_date IS NOT NULL AND TRUNC(cbb.expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 1 ELSE 0 END) > 0 THEN 'EXPIRED_INCLUDED' WHEN SUM(CASE WHEN cbb.lot_status = 'SALE_STOPPED' OR (cbb.sale_stop_date IS NOT NULL AND TRUNC(cbb.sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 1 ELSE 0 END) > 0 THEN 'SALE_STOPPED_INCLUDED' WHEN SUM(CASE WHEN cbb.lot_status = 'DEPLETED' THEN 1 ELSE 0 END) = COUNT(*) THEN 'DEPLETED_ONLY' WHEN SUM(cbb.on_hand_qty) = 0 THEN 'OUT_OF_STOCK' ELSE 'AVAILABLE' END AS inventory_fact_state, sr.risk_grade, sr.assessment_status, sr.shortage_yn, MAX(cbb.updated_at) AS updated_at FROM candidate_balance_base cbb LEFT JOIN sku_risk_agg sr ON sr.sku_id = cbb.sku_id GROUP BY cbb.sku_id, sr.risk_grade, sr.assessment_status, sr.shortage_yn ), paged_candidates AS ( SELECT q.*, COUNT(*) OVER () AS total_count FROM ( SELECT csa.sku_id, p.product_code, p.product_name, s.sku_code, s.sku_name, CASE WHEN s.storage_type = 'AMBIENT' THEN 'ROOM_TEMP' ELSE s.storage_type END AS storage_type, csa.current_qty, csa.available_qty, csa.reserved_qty, NVL(db.expected_disposal_qty, 0) AS expected_disposal_qty, csa.lot_count, csa.nearest_expiry_days, csa.nearest_expiry_date, csa.inventory_fact_state, csa.risk_grade, csa.assessment_status, csa.shortage_yn, csa.updated_at FROM candidate_sku_agg csa INNER JOIN sku s ON s.sku_id = csa.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN disposal_by_sku db ON db.sku_id = csa.sku_id ) q
ORDER BY CASE WHEN q.risk_grade IS NULL THEN 1 ELSE 0 END, CASE q.risk_grade WHEN 'DANGER' THEN 4 WHEN 'CAUTION' THEN 3 WHEN 'NORMAL' THEN 2 WHEN 'SAFE' THEN 1 ELSE 0 END ${sortDirection}, q.sku_code ASC
ORDER BY CASE WHEN q.${sortColumn} IS NULL THEN 1 ELSE 0 END, q.${sortColumn} ${sortDirection}, q.sku_code ASC
OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY ), owner_sales_point_counts AS ( SELECT ib.sku_id, COUNT(DISTINCT CASE WHEN NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) <> -1 THEN NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) END) AS owner_sales_point_count FROM inventory_balance ib INNER JOIN paged_candidates pc ON pc.sku_id = ib.sku_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) WHERE ib.is_deleted = 0 AND (sp.sales_point_id IS NULL OR (sp.is_deleted = 0 AND sp.active_yn = 'Y')) GROUP BY ib.sku_id ), balance_base AS ( SELECT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id, CASE WHEN ib.stock_sales_point_id IS NOT NULL THEN 'OWNED' WHEN ib.allocated_sales_point_id IS NOT NULL THEN 'ALLOCATED_ONLY' ELSE 'CENTER_ONLY' END AS sales_point_state, ib.allocated_sales_point_id, ib.warehouse_id, ib.lot_id, ib.on_hand_qty, ib.reserved_qty, ib.updated_at, l.lot_status, l.expiry_date, l.sale_stop_date FROM inventory_balance ib INNER JOIN candidate_keys ck ON ck.sku_id = ib.sku_id AND ck.sales_point_id = NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) INNER JOIN paged_candidates pc ON pc.sku_id = ib.sku_id LEFT JOIN warehouse active_w ON active_w.warehouse_id = ib.warehouse_id AND active_w.is_deleted = 0 AND active_w.active_yn = 'Y' LEFT JOIN lot l ON l.lot_id = ib.lot_id AND l.is_deleted = 0 WHERE ib.is_deleted = 0 ), unassigned_balance_base AS ( SELECT ib.sku_id, ib.warehouse_id, ib.lot_id, ib.on_hand_qty, ib.reserved_qty, ib.updated_at, l.lot_status, l.expiry_date, l.sale_stop_date FROM inventory_balance ib INNER JOIN paged_candidates pc ON pc.sku_id = ib.sku_id LEFT JOIN lot l ON l.lot_id = ib.lot_id AND l.is_deleted = 0 WHERE ib.is_deleted = 0 AND ib.allocated_sales_point_id IS NULL ), row_agg AS ( SELECT sku_id, sales_point_id, SUM(on_hand_qty + reserved_qty) AS current_qty, SUM(CASE WHEN lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (expiry_date IS NOT NULL AND TRUNC(expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (sale_stop_date IS NOT NULL AND TRUNC(sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE reserved_qty END) AS reserved_qty, SUM(CASE WHEN lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (expiry_date IS NOT NULL AND TRUNC(expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (sale_stop_date IS NOT NULL AND TRUNC(sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE on_hand_qty END) AS available_qty, CASE WHEN SUM(CASE WHEN sales_point_state = 'OWNED' THEN 1 ELSE 0 END) > 0 THEN 'OWNED' WHEN SUM(CASE WHEN sales_point_state = 'ALLOCATED_ONLY' THEN 1 ELSE 0 END) > 0 THEN 'ALLOCATED_ONLY' ELSE 'CENTER_ONLY' END AS sales_point_state, COUNT(DISTINCT lot_id) AS lot_count, TRUNC(MIN(CASE WHEN expiry_date IS NOT NULL THEN TRUNC(expiry_date) - TRUNC(CAST(#{asOfDate} AS DATE)) END)) AS nearest_expiry_days, MIN(expiry_date) AS nearest_expiry_date, CASE WHEN SUM(CASE WHEN lot_status = 'EXPIRED' OR (expiry_date IS NOT NULL AND TRUNC(expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 1 ELSE 0 END) > 0 THEN 'EXPIRED_INCLUDED' WHEN SUM(CASE WHEN lot_status = 'SALE_STOPPED' OR (sale_stop_date IS NOT NULL AND TRUNC(sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 1 ELSE 0 END) > 0 THEN 'SALE_STOPPED_INCLUDED' WHEN SUM(CASE WHEN lot_status = 'DEPLETED' THEN 1 ELSE 0 END) = COUNT(*) THEN 'DEPLETED_ONLY' WHEN SUM(on_hand_qty) = 0 THEN 'OUT_OF_STOCK' ELSE 'AVAILABLE' END AS inventory_fact_state, MAX(updated_at) AS updated_at FROM balance_base GROUP BY sku_id, sales_point_id ), unassigned_agg AS ( SELECT sku_id, SUM(on_hand_qty + reserved_qty) AS current_qty, SUM(CASE WHEN lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (expiry_date IS NOT NULL AND TRUNC(expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (sale_stop_date IS NOT NULL AND TRUNC(sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE on_hand_qty END) AS available_qty, SUM(CASE WHEN lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (expiry_date IS NOT NULL AND TRUNC(expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (sale_stop_date IS NOT NULL AND TRUNC(sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE reserved_qty END) AS reserved_qty, CASE WHEN SUM(CASE WHEN lot_status = 'EXPIRED' OR (expiry_date IS NOT NULL AND TRUNC(expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 1 ELSE 0 END) > 0 THEN 'EXPIRED_INCLUDED' WHEN SUM(CASE WHEN lot_status = 'SALE_STOPPED' OR (sale_stop_date IS NOT NULL AND TRUNC(sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 1 ELSE 0 END) > 0 THEN 'SALE_STOPPED_INCLUDED' WHEN SUM(CASE WHEN lot_status = 'DEPLETED' THEN 1 ELSE 0 END) = COUNT(*) THEN 'DEPLETED_ONLY' WHEN SUM(on_hand_qty) = 0 THEN 'OUT_OF_STOCK' ELSE 'AVAILABLE' END AS inventory_fact_state FROM unassigned_balance_base GROUP BY sku_id ), sku_warehouse_rows AS ( SELECT ub.sku_id, COALESCE(w.warehouse_code, 'UNKNOWN') AS warehouse_code, COALESCE(w.warehouse_name, '보관센터 미지정') AS warehouse_name, SUM(ub.on_hand_qty + ub.reserved_qty) AS quantity FROM unassigned_balance_base ub LEFT JOIN warehouse w ON w.warehouse_id = ub.warehouse_id AND w.is_deleted = 0 AND w.active_yn = 'Y' GROUP BY ub.sku_id, COALESCE(w.warehouse_code, 'UNKNOWN'), COALESCE(w.warehouse_name, '보관센터 미지정') ), sku_warehouse_agg AS ( SELECT sku_id, COUNT(*) AS location_count, JSON_ARRAYAGG(JSON_OBJECT( 'warehouseCode' VALUE warehouse_code, 'warehouseName' VALUE warehouse_name, 'quantity' VALUE quantity RETURNING CLOB ) ORDER BY warehouse_code RETURNING CLOB) AS locations_json FROM sku_warehouse_rows GROUP BY sku_id ), latest_policy AS ( SELECT ip.sku_id, COALESCE(ip.stock_sales_point_id, ip.allocated_sales_point_id, -1) AS sales_point_id, ip.safety_stock_qty, ROW_NUMBER() OVER ( PARTITION BY ip.sku_id, COALESCE(ip.stock_sales_point_id, ip.allocated_sales_point_id, -1) ORDER BY effective_from DESC NULLS LAST, inventory_policy_id DESC ) AS rn FROM inventory_policy ip INNER JOIN paged_candidates pc ON pc.sku_id = ip.sku_id WHERE ip.is_deleted = 0 AND (effective_from IS NULL OR effective_from <= #{asOfDate}) AND (effective_to IS NULL OR effective_to >= #{asOfDate}) ), policy_agg AS ( SELECT sku_id, sales_point_id, safety_stock_qty AS safety_qty FROM latest_policy WHERE rn = 1 ), latest_price AS ( SELECT sp.sku_id, sp.sales_point_id, sp.selling_price, ROW_NUMBER() OVER ( PARTITION BY sp.sku_id, sp.sales_point_id ORDER BY sp.effective_from DESC, sp.sku_channel_price_id DESC ) AS rn FROM sku_channel_price sp INNER JOIN paged_candidates pc ON pc.sku_id = sp.sku_id WHERE sp.is_deleted = 0 AND sp.effective_from <= #{asOfDate} AND (sp.effective_to IS NULL OR sp.effective_to >= #{asOfDate}) ), seller_facts AS ( SELECT ra.*, p.safety_qty, r.risk_grade, r.assessment_status, r.shortage_yn, r.risk_reason, lp.selling_price FROM row_agg ra LEFT JOIN policy_agg p ON p.sku_id = ra.sku_id AND p.sales_point_id = ra.sales_point_id LEFT JOIN risk_latest r ON r.sku_id = ra.sku_id AND r.sales_point_id = ra.sales_point_id LEFT JOIN latest_price lp ON lp.sku_id = ra.sku_id AND lp.sales_point_id = ra.sales_point_id AND lp.rn = 1 ), unassigned_facts AS ( SELECT ua.sku_id, ua.current_qty, ua.available_qty, ua.reserved_qty, ua.inventory_fact_state, ur.risk_grade, ur.assessment_status, ur.shortage_yn, ur.risk_reason FROM unassigned_agg ua LEFT JOIN risk_latest ur ON ur.sku_id = ua.sku_id AND ur.sales_point_id = -1 ), seller_agg AS ( SELECT sf.sku_id, JSON_ARRAYAGG(JSON_OBJECT( 'salesPointId' VALUE NULLIF(sf.sales_point_id, -1), 'salesPointCode' VALUE NVL(sp.sales_point_code, 'UNASSIGNED'), 'salesPointName' VALUE NVL(sp.sales_point_name, '판매처 미할당'), 'channelType' VALUE CASE WHEN sp.sales_point_code = 'GREETING' THEN 'GREETING' WHEN sp.sales_point_code = 'MODU_MATJIP' THEN 'ECOMMERCE' WHEN sp.sales_point_code LIKE 'DEPT_%' THEN 'HYUNDAI_DEPT' WHEN sp.sales_point_code LIKE 'HMART_%' THEN 'HMART' WHEN sp.sales_point_code IS NULL THEN 'CENTER' ELSE sc.channel_code END, 'currentQuantity' VALUE sf.current_qty, 'availableQuantity' VALUE sf.available_qty, 'reservedQuantity' VALUE sf.reserved_qty, 'riskGrade' VALUE sf.risk_grade, 'shortageYn' VALUE sf.shortage_yn, 'salesPointState' VALUE sf.sales_point_state, 'warehouseName' VALUE CAST(NULL AS VARCHAR2(200)), 'sellingPrice' VALUE sf.selling_price RETURNING CLOB ) ORDER BY NVL(sp.sales_point_code, 'UNASSIGNED') RETURNING CLOB) AS sales_points_json FROM seller_facts sf LEFT JOIN sales_point sp ON sp.sales_point_id = sf.sales_point_id LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id GROUP BY sf.sku_id ), sku_agg AS ( SELECT sf.sku_id, SUM(current_qty) AS current_qty, SUM(available_qty) AS available_qty, SUM(reserved_qty) AS reserved_qty, SUM(safety_qty) AS safety_qty, CASE WHEN SUM(CASE WHEN inventory_fact_state = 'EXPIRED_INCLUDED' THEN 1 ELSE 0 END) > 0 THEN 'EXPIRED_INCLUDED' WHEN SUM(CASE WHEN inventory_fact_state = 'SALE_STOPPED_INCLUDED' THEN 1 ELSE 0 END) > 0 THEN 'SALE_STOPPED_INCLUDED' WHEN SUM(CASE WHEN inventory_fact_state = 'DEPLETED_ONLY' THEN 1 ELSE 0 END) = COUNT(*) THEN 'DEPLETED_ONLY' WHEN SUM(CASE WHEN inventory_fact_state = 'OUT_OF_STOCK' THEN 1 ELSE 0 END) = COUNT(*) THEN 'OUT_OF_STOCK' ELSE 'AVAILABLE' END AS inventory_fact_state, sr.risk_grade, sr.assessment_status, sr.shortage_yn, SUM(lot_count) AS lot_count, MIN(nearest_expiry_days) AS nearest_expiry_days, MIN(nearest_expiry_date) AS nearest_expiry_date, MAX(updated_at) AS updated_at FROM seller_facts sf LEFT JOIN sku_risk_agg sr ON sr.sku_id = sf.sku_id GROUP BY sf.sku_id, sr.risk_grade, sr.assessment_status, sr.shortage_yn ) SELECT sa.sku_id, pc.product_code, pc.product_name, sup.supplier_name AS supplier_name, p.image_url, pc.sku_code, pc.sku_name, c.category_id, c.category_name, c.category_level, cp.category_id AS parent_category_id, cp.category_name AS parent_category_name, cp.category_level AS parent_category_level, cg.category_id AS grandparent_category_id, cg.category_name AS grandparent_category_name, cg.category_level AS grandparent_category_level, CAST(NULL AS VARCHAR2(50)) AS channel_type, CAST(NULL AS VARCHAR2(100)) AS sales_point_code, CAST(NULL AS VARCHAR2(200)) AS sales_point_name, pc.storage_type, CAST(NULL AS NUMBER(15,3)) AS selling_price, sa.current_qty, sa.available_qty, sa.reserved_qty, pc.expected_disposal_qty, sa.safety_qty, sa.inventory_fact_state, sa.risk_grade, sa.assessment_status, sa.shortage_yn, CAST(NULL AS VARCHAR2(1000)) AS risk_reason, swa.locations_json, swa.locations_json AS unassigned_locations_json, swa.location_count, swa.location_count AS unassigned_location_count, owner_counts.owner_sales_point_count, sellers.sales_points_json, uf.current_qty AS unassigned_current_qty, uf.available_qty AS unassigned_available_qty, uf.reserved_qty AS unassigned_reserved_qty, uf.inventory_fact_state AS unassigned_inventory_fact_state, uf.shortage_yn AS unassigned_shortage_yn, uf.risk_grade AS unassigned_risk_grade, uf.assessment_status AS unassigned_assessment_status, uf.risk_reason AS unassigned_risk_reason, sa.lot_count, sa.nearest_expiry_days, sa.nearest_expiry_date, sa.updated_at, pc.total_count FROM paged_candidates pc INNER JOIN sku_agg sa ON sa.sku_id = pc.sku_id INNER JOIN sku s ON s.sku_id = pc.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN supplier sup ON sup.supplier_id = p.supplier_id AND sup.is_deleted = 0 LEFT JOIN category c ON c.category_id = p.category_id LEFT JOIN category cp ON cp.category_id = c.parent_category_id AND cp.is_deleted = 0 LEFT JOIN category cg ON cg.category_id = cp.parent_category_id AND cg.is_deleted = 0 LEFT JOIN sku_warehouse_agg swa ON swa.sku_id = pc.sku_id LEFT JOIN seller_agg sellers ON sellers.sku_id = pc.sku_id LEFT JOIN owner_sales_point_counts owner_counts ON owner_counts.sku_id = pc.sku_id LEFT JOIN unassigned_facts uf ON uf.sku_id = pc.sku_id
ORDER BY CASE WHEN pc.risk_grade IS NULL THEN 1 ELSE 0 END, CASE pc.risk_grade WHEN 'DANGER' THEN 4 WHEN 'CAUTION' THEN 3 WHEN 'NORMAL' THEN 2 WHEN 'SAFE' THEN 1 ELSE 0 END ${sortDirection}, pc.sku_code ASC
ORDER BY CASE WHEN pc.${sortColumn} IS NULL THEN 1 ELSE 0 END, pc.${sortColumn} ${sortDirection}, pc.sku_code ASC

WITH risk_rows AS ( SELECT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id, ra.risk_grade, ra.shortage_yn, ra.updated_at, ROW_NUMBER() OVER ( PARTITION BY ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) ORDER BY ra.updated_at DESC, ra.risk_assessment_id DESC ) AS rn FROM risk_assessment ra INNER JOIN inventory_balance ib ON ib.inventory_balance_id = ra.inventory_balance_id AND ib.is_deleted = 0 WHERE ra.is_deleted = 0 ), risk_latest AS ( SELECT sku_id, sales_point_id, CASE risk_grade WHEN 'GOOD' THEN 'SAFE' WHEN 'WARNING' THEN 'CAUTION' WHEN 'CRITICAL' THEN 'DANGER' ELSE risk_grade END AS risk_grade, CASE WHEN risk_grade IS NULL THEN 'UNASSESSED' ELSE 'ASSESSED' END AS assessment_status, shortage_yn FROM risk_rows WHERE rn = 1 ), valid_scope_keys AS ( SELECT DISTINCT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id FROM inventory_balance ib INNER JOIN sku s ON s.sku_id = ib.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id
), sku_risk_agg AS ( SELECT scope.sku_id, CASE WHEN COUNT(*) <> COUNT(r.risk_grade) THEN NULL WHEN SUM(CASE WHEN r.risk_grade = 'DANGER' THEN 1 ELSE 0 END) > 0 THEN 'DANGER' WHEN SUM(CASE WHEN r.risk_grade = 'CAUTION' THEN 1 ELSE 0 END) > 0 THEN 'CAUTION' WHEN SUM(CASE WHEN r.risk_grade = 'NORMAL' THEN 1 ELSE 0 END) > 0 THEN 'NORMAL' WHEN SUM(CASE WHEN r.risk_grade = 'SAFE' THEN 1 ELSE 0 END) > 0 THEN 'SAFE' ELSE NULL END AS risk_grade, CASE WHEN COUNT(*) = COUNT(r.risk_grade) THEN 'ASSESSED' ELSE 'UNASSESSED' END AS assessment_status, CASE WHEN SUM(CASE WHEN r.shortage_yn = 'Y' THEN 1 ELSE 0 END) > 0 THEN 'Y' ELSE 'N' END AS shortage_yn FROM valid_scope_keys scope LEFT JOIN risk_latest r ON r.sku_id = scope.sku_id AND r.sales_point_id = scope.sales_point_id GROUP BY scope.sku_id ), candidate_keys AS ( SELECT DISTINCT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id FROM inventory_balance ib INNER JOIN sku s ON s.sku_id = ib.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id LEFT JOIN sku_risk_agg sr ON sr.sku_id = ib.sku_id
) SELECT COUNT(DISTINCT sku_id) FROM candidate_keys

WITH risk_rows AS ( SELECT /*+ MATERIALIZE */ ib.inventory_balance_id, ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id, ra.risk_grade, ra.shortage_yn, ra.updated_at, ROW_NUMBER() OVER ( PARTITION BY ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) ORDER BY ra.updated_at DESC, ra.risk_assessment_id DESC ) AS scope_rn, ROW_NUMBER() OVER ( PARTITION BY ib.inventory_balance_id ORDER BY ra.updated_at DESC, ra.risk_assessment_id DESC ) AS balance_rn FROM risk_assessment ra INNER JOIN inventory_balance ib ON ib.inventory_balance_id = ra.inventory_balance_id AND ib.is_deleted = 0 WHERE ra.is_deleted = 0 ), risk_latest AS ( SELECT sku_id, sales_point_id, CASE risk_grade WHEN 'GOOD' THEN 'SAFE' WHEN 'WARNING' THEN 'CAUTION' WHEN 'CRITICAL' THEN 'DANGER' ELSE risk_grade END AS risk_grade, CASE WHEN risk_grade IS NULL THEN 'UNASSESSED' ELSE 'ASSESSED' END AS assessment_status, shortage_yn FROM risk_rows WHERE scope_rn = 1 ), latest_shortage AS ( SELECT inventory_balance_id, shortage_yn FROM risk_rows WHERE balance_rn = 1 ), valid_scope_keys AS ( SELECT DISTINCT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id FROM inventory_balance ib INNER JOIN sku s ON s.sku_id = ib.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id
), sku_risk_agg AS ( SELECT scope.sku_id, CASE WHEN COUNT(*) <> COUNT(r.risk_grade) THEN NULL WHEN SUM(CASE WHEN r.risk_grade = 'DANGER' THEN 1 ELSE 0 END) > 0 THEN 'DANGER' WHEN SUM(CASE WHEN r.risk_grade = 'CAUTION' THEN 1 ELSE 0 END) > 0 THEN 'CAUTION' WHEN SUM(CASE WHEN r.risk_grade = 'NORMAL' THEN 1 ELSE 0 END) > 0 THEN 'NORMAL' WHEN SUM(CASE WHEN r.risk_grade = 'SAFE' THEN 1 ELSE 0 END) > 0 THEN 'SAFE' ELSE NULL END AS risk_grade, CASE WHEN COUNT(*) = COUNT(r.risk_grade) THEN 'ASSESSED' ELSE 'UNASSESSED' END AS assessment_status, CASE WHEN SUM(CASE WHEN r.shortage_yn = 'Y' THEN 1 ELSE 0 END) > 0 THEN 'Y' ELSE 'N' END AS shortage_yn FROM valid_scope_keys scope LEFT JOIN risk_latest r ON r.sku_id = scope.sku_id AND r.sales_point_id = scope.sales_point_id GROUP BY scope.sku_id ), candidate_keys AS ( SELECT DISTINCT ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id FROM inventory_balance ib INNER JOIN sku s ON s.sku_id = ib.sku_id INNER JOIN product p ON p.product_id = s.product_id LEFT JOIN sales_point sp ON sp.sales_point_id = NVL(ib.stock_sales_point_id, ib.allocated_sales_point_id) LEFT JOIN sales_channel sc ON sc.sales_channel_id = sp.sales_channel_id LEFT JOIN sku_risk_agg sr ON sr.sku_id = ib.sku_id
), balance_base AS ( SELECT ib.inventory_balance_id, ib.sku_id, NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) AS sales_point_id, ib.on_hand_qty, ib.reserved_qty, ib.updated_at, l.lot_status, l.expiry_date, l.sale_stop_date FROM inventory_balance ib INNER JOIN candidate_keys ck ON ck.sku_id = ib.sku_id AND ck.sales_point_id = NVL(ib.stock_sales_point_id, NVL(ib.allocated_sales_point_id, -1)) LEFT JOIN warehouse active_w ON active_w.warehouse_id = ib.warehouse_id AND active_w.is_deleted = 0 AND active_w.active_yn = 'Y' LEFT JOIN lot l ON l.lot_id = ib.lot_id AND l.is_deleted = 0 WHERE ib.is_deleted = 0 ), row_agg AS ( SELECT bb.sku_id, bb.sales_point_id, SUM(bb.on_hand_qty + bb.reserved_qty) AS current_qty, SUM(CASE WHEN bb.lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (bb.expiry_date IS NOT NULL AND TRUNC(bb.expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (bb.sale_stop_date IS NOT NULL AND TRUNC(bb.sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE bb.reserved_qty END) AS reserved_qty, SUM(CASE WHEN bb.lot_status IN ('EXPIRED', 'SALE_STOPPED', 'DEPLETED') OR (bb.expiry_date IS NOT NULL AND TRUNC(bb.expiry_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) OR (bb.sale_stop_date IS NOT NULL AND TRUNC(bb.sale_stop_date) <= TRUNC(CAST(#{asOfDate} AS DATE))) THEN 0 ELSE bb.on_hand_qty END) AS available_qty, MAX(CASE WHEN ls.shortage_yn = 'Y' THEN 1 ELSE 0 END) AS shortage_count, MAX(bb.updated_at) AS updated_at FROM balance_base bb LEFT JOIN latest_shortage ls ON ls.inventory_balance_id = bb.inventory_balance_id GROUP BY bb.sku_id, bb.sales_point_id ), latest_policy AS ( SELECT sku_id, COALESCE(stock_sales_point_id, allocated_sales_point_id, -1) AS sales_point_id, safety_stock_qty, ROW_NUMBER() OVER ( PARTITION BY sku_id, COALESCE(stock_sales_point_id, allocated_sales_point_id, -1) ORDER BY effective_from DESC NULLS LAST, inventory_policy_id DESC ) AS rn FROM inventory_policy WHERE is_deleted = 0 AND (effective_from IS NULL OR effective_from <= #{asOfDate}) AND (effective_to IS NULL OR effective_to >= #{asOfDate}) ), policy_agg AS ( SELECT sku_id, sales_point_id, safety_stock_qty AS safety_qty FROM latest_policy WHERE rn = 1 ), seller_facts AS ( SELECT ra.*, p.safety_qty FROM row_agg ra LEFT JOIN policy_agg p ON p.sku_id = ra.sku_id AND p.sales_point_id = ra.sales_point_id ), sku_totals AS ( SELECT sf.sku_id, SUM(sf.current_qty) AS current_qty, SUM(sf.available_qty) AS available_qty, SUM(sf.reserved_qty) AS reserved_qty, CASE WHEN MAX(sf.shortage_count) = 1 THEN 1 ELSE 0 END AS under_safety_count, CASE WHEN sr.risk_grade = 'DANGER' THEN 1 ELSE 0 END AS danger_risk_count, CASE WHEN sr.risk_grade = 'CAUTION' THEN 1 ELSE 0 END AS caution_risk_count, CASE WHEN sr.risk_grade = 'SAFE' THEN 1 ELSE 0 END AS safe_risk_count, MAX(sf.updated_at) AS updated_at FROM seller_facts sf LEFT JOIN sku_risk_agg sr ON sr.sku_id = sf.sku_id GROUP BY sf.sku_id, sr.risk_grade, sr.shortage_yn ) SELECT SUM(current_qty) AS total_current_qty, SUM(available_qty) AS total_available_qty, SUM(reserved_qty) AS total_reserved_qty, NVL(SUM(under_safety_count), 0) AS under_safety_count, NVL(SUM(danger_risk_count), 0) AS danger_risk_count, NVL(SUM(caution_risk_count), 0) AS caution_risk_count, NVL(SUM(safe_risk_count), 0) AS safe_risk_count, MAX(updated_at) AS last_sync_time FROM sku_totals
